<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGroupMembership\Application\Usecase\Update;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\UserGroupMembershipRef;
use Civi\Lughauth\Features\Access\UserGroupMembership\Application\Service\Visibility\UserGroupMembershipVisibilityService;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserGroupMembershipUpdateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserGroupMembershipVisibilityService $visibility,
        private readonly UserGroupMembershipWriteGateway $writer,
    ) {
    }

    public function allowUpdate(?UserGroupMembershipRef $ref = null): Allow
    {
        $this->logDebug("Check allow update usecase for User group membership");
        $span = $this->startSpan("Check allow update usecase for User group membership");
        try {
            $result = $this->dispatcher->dispatch(new UserGroupMembershipUpdateAllowDecision(Allow::allowed('update', 'Allowed to update by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fixedFields(?UserGroupMembershipRef $ref = null): array
    {
        $this->logDebug("Check fixed fields for update usecase for User group membership");
        $span = $this->startSpan("Check fixed fields for update usecase for User group membership");
        try {
            return $this->visibility->fieldsToFix($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function update(string $uid, UserGroupMembershipUpdateParams $params): UserGroupMembershipUpdateResult
    {
        $this->logDebug("Run update usecase for User group membership");
        $span = $this->startSpan("Run update usecase for User group membership");
        try {
            $ref = new UserGroupMembershipRef($uid);
            $allow = $this->allowUpdate($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to update User group membership');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new UserGroupMembershipUpdateCheck($params, $original));
            $enriched = $this->dispatcher->dispatch(new UserGroupMembershipUpdateEnrich($params, $original, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $modified = $original->update($input);
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new UserGroupMembershipUpdateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
